<script setup>
import {onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api} from '../bridge/jcefBridge';import PageShell from '../components/common/PageShell.vue';
const detailTab=ref('meta'),rows=ref([]),agents=ref([]),page=ref(1),pageSize=ref(30),total=ref(0),detail=ref(null),selected=ref([]),loading=ref(false);const filter=reactive({status:'',agentId:null,messageType:'',keyword:''});const statuses=[['completed','已完成'],['failed','失败'],['cancelled','已取消'],['processing','处理中']];const types=[['direct_run','直接运行'],['chat_turn','聊天对话'],['workflow_node','工作流节点'],['scheduled_run','定时运行'],['multimodal_analysis','多模态分析'],['agent_distillation','Agent 蒸馏'],['environment_distillation','环境蒸馏']];const deletable=x=>x.messageType!=='chat_turn';const statusText=v=>statuses.find(x=>x[0]===v)?.[1]||v;const typeText=v=>types.find(x=>x[0]===v)?.[1]||v||'-';
async function load(){loading.value=true;try{const x=await api('modelLogs.list',{page:page.value,pageSize:pageSize.value,...filter});rows.value=x.rows;total.value=x.total;agents.value=x.agents||[]}finally{loading.value=false}}function search(){page.value=1;load()}async function show(x){detail.value=await api('modelLogs.detail',{id:x.id});detailTab.value='meta'}async function removeSelected(){await ElMessageBox.confirm(`确定删除选中的 ${selected.value.length} 条日志吗？`,'批量删除',{type:'warning'});await api('modelLogs.deleteBatch',{ids:selected.value.map(x=>x.id)});ElMessage.success('日志已删除');selected.value=[];load()}function tokenValue(u,...paths){for(const path of paths){const value=path.split('.').reduce((v,k)=>v?.[k],u);if(Number.isFinite(Number(value)))return Number(value)}return 0}function totalTokens(u={}){const explicit=tokenValue(u,'total_tokens');if(explicit>0)return explicit;const input=tokenValue(u,'input_tokens')||tokenValue(u,'prompt_tokens'),output=tokenValue(u,'output_tokens')||tokenValue(u,'completion_tokens');return input+output+tokenValue(u,'cache_creation_input_tokens')+tokenValue(u,'cache_read_input_tokens')}function compact(n){return n>=1e6?(n/1e6).toFixed(1).replace('.0','')+'m':n>=1e3?(n/1e3).toFixed(1).replace('.0','')+'k':`${n} tokens`}function tokenDetails(value,prefix=''){if(!value||typeof value!=='object'||Array.isArray(value))return[];return Object.entries(value).flatMap(([key,entry])=>{const path=prefix?`${prefix}.${key}`:key;if(entry&&typeof entry==='object'&&!Array.isArray(entry))return tokenDetails(entry,path);const number=Number(entry);return Number.isFinite(number)?[{label:path,value:number}]:[]})}function agentName(id){return agents.value.find(x=>x.id===id)?.name||'-'}onMounted(load)
</script>
<template><PageShell title="模型日志" :loading="loading"><template #actions><el-button :disabled="!selected.length" type="danger" plain @click="removeSelected">批量删除{{selected.length?`（${selected.length}）`:''}}</el-button></template><div class="log-page"><div class="filter-bar"><el-select v-model="filter.status" clearable placeholder="全部状态"><el-option v-for="x in statuses" :key="x[0]" :value="x[0]" :label="x[1]"/></el-select><el-select v-model="filter.agentId" clearable filterable placeholder="全部 Agent"><el-option v-for="x in agents" :key="x.id" :value="x.id" :label="x.name"/></el-select><el-select v-model="filter.messageType" clearable placeholder="全部 Agent 类型"><el-option v-for="x in types" :key="x[0]" :value="x[0]" :label="x[1]"/></el-select><el-input v-model="filter.keyword" clearable placeholder="请求、响应或错误关键字" @keyup.enter="search"/><el-button type="primary" @click="search">筛选</el-button></div><div class="log-table"><el-table :data="rows" height="100%" @selection-change="x=>selected=x" @row-dblclick="show"><el-table-column type="selection" width="42" :selectable="deletable"/><el-table-column prop="id" label="编号" width="72"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag size="small" :type="row.status==='completed'?'success':row.status==='failed'?'danger':'info'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="Agent" min-width="120"><template #default="{row}">{{agentName(row.agentId)}}</template></el-table-column><el-table-column label="Agent 类型" min-width="115"><template #default="{row}">{{typeText(row.messageType)}}</template></el-table-column><el-table-column prop="modelName" label="模型" min-width="130"/><el-table-column label="Token" width="105"><template #default="{row}"><el-popover v-if="totalTokens(row.usage)" placement="left" trigger="hover" :show-after="120" :hide-after="80" :teleported="true" width="300" popper-class="token-usage-popper"><template #reference><el-tag effect="plain" class="usage-pill">{{compact(totalTokens(row.usage))}}</el-tag></template><div class="token-usage-card"><header><strong>Token usage</strong><small>日志 #{{row.id}}</small></header><div v-for="x in tokenDetails(row.usage)" :key="x.label" :class="{'token-total':x.label==='total_tokens'}"><span>{{x.label}}</span><strong>{{x.value.toLocaleString()}}</strong></div></div></el-popover><span v-else>-</span></template></el-table-column><el-table-column prop="createdAt" label="时间" width="170"/><el-table-column label="操作" width="75"><template #default="{row}"><el-button link @click.stop="show(row)">详情</el-button></template></el-table-column></el-table></div><div class="pagination-row"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[20,30,50,100]" layout="total, sizes, prev, pager, next, jumper" @change="load"/></div></div><el-drawer v-model="detail" title="日志详情" size="65%"><el-tabs v-if="detail" v-model="detailTab"><el-tab-pane label="元数据" name="meta"><div class="meta-grid"><div v-for="([label,value]) in [['日志编号',detail.id],['状态',statusText(detail.status)],['Agent',agentName(detail.agentId)],['Agent 类型',typeText(detail.messageType)],['来源类型',detail.sourceType],['来源编号',detail.sourceId],['供应商',detail.providerName],['模型',detail.modelName],['开始时间',detail.startedAt],['结束时间',detail.finishedAt],['创建时间',detail.createdAt]]" :key="label"><span>{{label}}</span><strong>{{value??'-'}}</strong></div></div><el-divider>Token usage</el-divider><div v-if="totalTokens(detail.usage)" class="token-detail-grid"><div v-for="x in tokenDetails(detail.usage)" :key="x.label" :class="{'token-total':x.label==='total_tokens'}"><span>{{x.label}}</span><strong>{{x.value.toLocaleString()}}</strong></div></div><el-empty v-else description="No token usage" :image-size="48"/><template v-if="detail.errorData"><el-divider>错误信息</el-divider><pre class="error-json">{{detail.errorData}}</pre></template></el-tab-pane><el-tab-pane label="请求参数" name="request"><pre class="json">{{JSON.stringify(detail.requestData||{},null,2)}}</pre></el-tab-pane><el-tab-pane label="响应参数" name="response"><pre class="json">{{JSON.stringify(detail.responseData||{},null,2)}}</pre></el-tab-pane></el-tabs></el-drawer></PageShell></template>
